import{_ as t,o,c as a,a2 as s}from"./chunks/framework.DrEOy6Sl.js";const p=JSON.parse('{"title":"How it works","description":"","frontmatter":{},"headers":[],"relativePath":"reference/how-it-works.md","filePath":"reference/how-it-works.md","lastUpdated":1794407877000}'),d={name:"reference/how-it-works.md"};function r(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><p>What happens at build time and how each request is answered.</p><p>At build time, three tasks run before <code>processResources</code>:</p><ol><li><code>svelteInstall</code> installs dependencies from your lockfile.</li><li><code>svelteBuild</code> runs your build script.</li><li><code>svelteBundle</code> copies the output to <code>ktor-svelte/public/</code> in your resources, and writes <code>ktor-svelte/manifest.json</code> with a hash of every file.</li></ol><p><code>svelteBundle</code> leaves out hidden files such as <code>.env</code> (but keeps <code>.well-known</code>), source maps and symlinks, and warns about any hidden files it skipped. <code>SvelteSource.Directory</code> also ignores hidden files and symlinks, but serves source maps. It streams each file through a non-blocking file channel with its exact <code>Content-Length</code>, which makes it a good fit for large builds served from a volume.</p><p>At run time, <code>install(Svelte)</code> adds a catch-all route. Ktor always prefers more specific routes, so yours win. GET and HEAD requests that reach the catch-all are resolved in this order:</p><table tabindex="0"><thead><tr><th>Step</th><th>Request</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td>Path under an API prefix</td><td>Not handled, so Ktor returns its normal 404</td></tr><tr><td>2</td><td>Exact file in the manifest</td><td>Serve the file</td></tr><tr><td>3</td><td><code>/about</code> when <code>about.html</code> exists, or <code>/about/</code> when <code>about/index.html</code> exists</td><td>Serve the page</td></tr><tr><td>4</td><td><code>/about/</code> when only <code>about.html</code> exists, or <code>/about</code> when only <code>about/index.html</code> exists</td><td>308 redirect to the form that exists, keeping the query string</td></tr><tr><td>5</td><td>Missing path under <code>/_app/</code>, <code>/.well-known/</code> or <code>/_ktor-svelte/</code>, or any path with a file extension</td><td>404, never the fallback</td></tr><tr><td>6</td><td>Other path, with a fallback page and a request that accepts HTML, or a path matching <code>paramRoutes</code></td><td>Serve the fallback with status 200</td></tr><tr><td>7</td><td>Anything else</td><td><code>404.html</code> with status 404 if it exists, otherwise a plain 404</td></tr></tbody></table><p>Because your routes always win, a Ktor <code>GET /about</code> hides a prerendered <code>about.html</code>. The app warns about every such route at startup, for example <code>ktor-svelte: the Ktor route GET /about hides the frontend page about.html.</code> Routes under your API prefixes and routes with parameters are not checked.</p><p>Step 4 exists because prerendered pages load assets with relative paths, so serving <code>about.html</code> at <code>/about/</code> would break them. Every file from the build answers <code>Range: bytes=...</code> requests with 206 and <code>Content-Range</code>, so videos can seek and downloads can resume. Ranges are always served without <code>Content-Encoding</code>, <code>If-Range</code> is honoured, and a range past the end of the file answers 416. Other methods on a path that resolves to a page or file, such as a POST to <code>/about</code>, answer 405 with <code>Allow: GET, HEAD, OPTIONS</code>, and OPTIONS answers 204 with the same header. Paths that resolve to nothing stay 404. In development, POST, PUT, PATCH and DELETE still go to Vite first.</p><p>Step 5 lets SvelteKit recover from stale chunks after a deploy by doing a full page reload.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><code>adapter-static</code> only. There is no Node process in production, so <code>+page.server.ts</code>, <code>+server.ts</code> and form actions are not supported. Ktor is the backend. The <a href="./faq">FAQ</a> explains why and what to use instead.</li><li>The app is mounted at the root. <code>paths.base</code> is not supported yet.</li><li>Files are served whole or as one byte range. Requests for several ranges at once get the whole file. Very large media still makes the JAR large, so a CDN or object storage is often the better home for it.</li><li><code>generateTs</code> builds on Ktor&#39;s OpenAPI support, which Ktor still marks as experimental.</li></ul>',12)])])}const w=t(d,[["render",r]]);export{p as __pageData,w as default};
